// Find the viewer count text from the thumbnail overlay badge
const card = element.closest('[data-test-selector="TitleAndChannel"]') 
  ? element.closest('[data-test-selector="TitleAndChannel"]').closest('.Layout-sc-1xcs6mc-0')
  : element.closest('.Layout-sc-1xcs6mc-0.cexlzi') || element.closest('.cexlzi');

if (!card) return;

const statEl = card.querySelector('.ScMediaCardStatWrapper-sc-anph5i-0');
if (!statEl) return;

const viewerText = statEl.textContent.trim();
if (!viewerText) return;

// Check if we've already injected; find or create the inline viewer line
let injected = element.parentNode.querySelector('.ext-viewer-count-inline');
if (!injected) {
  injected = document.createElement('p');
  injected.className = 'ext-viewer-count-inline';
  injected.style.cssText = 'margin: 2px 0 0 0; font-size: 1.15rem; font-weight: 600; color: #bf94ff; line-height: 1.3;';
  element.parentNode.insertBefore(injected, element.nextSibling);
}

// Always overwrite to keep it fresh and idempotent
injected.textContent = '👁 ' + viewerText;
